SYN-MOD-CP3-001:
IMPORT math.
NUMBER n.
INPUT(n).
NUMBER root = math.FLOOR(math.SQRT(n)).
IF (root * root == n) {
    DISPLAYNL("SQUARE").
} ELSE {
    DISPLAYNL("NOT SQUARE").
}

